blocchi.codice:
extends Control

@onready var question_label: Label = $MarginContainer/VBoxContainer/QuestionLabel

func _ready() -> void:
	# Creiamo una nuova risorsa AtlasTexture da codice
	var icon_texture := AtlasTexture.new()

	# Carichiamo il foglio di sprite che contiene tutte le icone
	icon_texture.atlas = load("res://icon.svg") as Texture2D

	# Definiamo la regione di ritaglio con Rect2(posizione_x, posizione_y, larghezza, altezza)
	# Prendiamo un riquadro di 64x64 pixel a partire dalle coordinate (0, 0)
	icon_texture.region = Rect2(0.0, 0.0, 64.0, 64.0)
